  (gen_random_uuid(), 1, 'Register', 'Sekiz bitlik sensör değeri AX''in alt yarısında işlenecek. Hangi yazmacı hedeflersin?', 'Sekiz bitlik alt bölüm olan AL yazmacını kullanırım.', 'AH''yi seçip bunun AX''in alt byte''ı olduğunu varsayarım.', 'AX''e yalnızca sekiz bit yazarak üst byte''ın korunacağını kabul ederim.', 'Boyutu denetlemeden 16 bitlik değeri sekiz bitlik hedefe taşırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Register', 'Bir bellek tablosunun başlangıç ofseti sonraki erişimlerde tekrar kullanılacak. 8086''da hangi yazmaç uygundur?', 'Taban adresi için BX yazmacını kullanırım.', 'CX''i taban yazmacı seçip bütün adresleme biçimlerinde geçerli sayarım.', 'IP''yi veri tablosunun kalıcı ofseti olarak değiştiririm.', 'SS değerini tablo ofseti yapıp yığın bölümünü kaybederim.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Register', 'Bir döngü belirli sayıda tekrar çalışacak ve LOOP kullanılacak. Sayacı nerede tutarsın?', 'Tekrar sayısını CX yazmacında tutarım.', 'DX''i kullanıp LOOP komutunun onu otomatik azaltmasını beklerim.', 'SP''yi sayaç yapıp yığın işlemlerinin değeri değiştirmeyeceğini varsayarım.', 'IP''yi azaltarak döngü sayısını takip etmeye çalışırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Register', 'On altı bitlik işaretsiz çarpımın üst yarısını ayrıca denetlemen gerekiyor. Sonucun bu kısmını nerede ararsın?', 'MUL sonrasında üst yarıyı DX yazmacında kontrol ederim.', 'Üst yarının BX''e otomatik yazılacağını varsayarım.', 'Yalnızca AX''i okuyup üst yarının her zaman sıfır olduğunu kabul ederim.', 'Çarpımdan sonra DX''i temizleyip taşan kısmı incelemeden kullanırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Register', 'İşlemci sıradaki komutun kod bölümü içindeki ofsetini izlemeli. Hangi yazmacı esas alırsın?', 'Sıradaki komut ofsetini IP yazmacından izlerim.', 'CS''yi her komutta ofset kadar artırırım.', 'SP''yi komut göstergesi olarak kullanırım.', 'IP''yi veri adresiyle değiştirip yürütme akışını belirsizleştiririm.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Memory', 'Kod, veri ve yığın alanlarını ayrı tutan 8086 programında veri erişimleri hangi segment yazmacına dayanmalı?', 'Normal veri erişimleri için DS yazmacını doğru veri segmentiyle yüklerim.', 'CS''yi veri segmenti yapıp komut getirme adresini de aynı anda koruduğumu varsayarım.', 'SS''yi bütün veri tablolarının varsayılan segmenti kabul ederim.', 'Segment yazmaçlarını hazırlamadan rastgele fiziksel alana veri yazarım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Stack', 'PUSH ve POP işlemleri yanlış bellek bölgesine gidiyor. İlk hangi segment yazmacını kontrol edersin?', 'Yığın bölümünü belirleyen SS yazmacını kontrol ederim.', 'DS''nin bütün yığın işlemlerini yönettiğini varsayarım.', 'CS''yi değiştirerek yığın konumunu düzeltmeye çalışırım.', 'SS ve SP''yi doğrulamadan dönüş adreslerini kullanmaya devam ederim.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Assembly', 'Bir byte değeri başka bir byte yazmaca kopyalanacak. MOV için hangi boyut kuralını uygularsın?', 'Kaynak ve hedef operandların aynı genişlikte olmasını sağlarım.', 'Sekiz bitlik hedefe 16 bitlik kaynağı doğrudan verip üst kısmın yok sayılmasını beklerim.', 'MOV komutunun farklı boyutları her zaman otomatik dönüştürdüğünü varsayarım.', 'Boyut uyuşmazlığını gizleyip yanlış opcode''u çalıştırırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Flag', 'Bir giriş değerinde belirli bitlerin açık olup olmadığını veriyi değiştirmeden sınayacaksın. Ne kullanırsın?', 'Uygun maske ile TEST uygulayıp oluşan durum bayraklarını okurum.', 'AND uygulayıp operandın değişmesini önemsiz sayarım.', 'MOV ile maskeyi yükleyip bayrakların güncelleneceğini varsayarım.', 'Giriş değerini sıfırlayıp test sonucunu eski değere göre yorumlarım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Flag', 'CMP sonrasında iki değer eşitse başarı yoluna geçeceksin. Hangi koşulu izlersin?', 'Zero Flag set olduğunda eşitlik dalına giderim.', 'Carry Flag set olduğunda değerleri her durumda eşit sayarım.', 'Direction Flag değerini eşitlik göstergesi olarak kullanırım.', 'CMP''den sonra bayrakları değiştiren başka komut çalıştırıp eski sonucu dallanmada kullanırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Flag', 'İşaretsiz toplamada üst bitten taşıma oluşursa hata yoluna geçilecek. Hangi bayrağı kontrol edersin?', 'İşaretsiz taşıma için Carry Flag değerini kontrol ederim.', 'Yalnızca Overflow Flag ile işaretsiz taşmayı belirlerim.', 'Zero Flag sıfırsa carry oluştuğunu kabul ederim.', 'Carry durumunu okumadan taşmış sonucu güvenli adres olarak kullanırım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Assembly', 'Byte içindeki bitleri kaybetmeden sağa döndürmek istiyorsun. Hangi işlem davranışını seçersin?', 'ROR ile sağdan çıkan bitleri sol uçtan geri alırım.', 'SHR kullanıp düşen bitlerin sol uca döneceğini varsayarım.', 'SAR uygulayıp işaret bitinin dairesel taşındığını kabul ederim.', 'Kaydırma sayısını operand genişliğini düşünmeden kullanıp sonucu doğrulamam.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Addressing', 'Sabit bir ofsetteki byte''a yazmaç eklemeden erişmek gerekiyor. Hangi adresleme yaklaşımını seçersin?', 'Bellek operandında doğrudan ofset kullanırım.', 'BX ve SI''yi zorunlu olarak ekleyip bunun doğrudan adresleme olduğunu söylerim.', 'Immediate değeri bellek adresi yerine veri olarak kullanırım.', 'Ofsetin ait olduğu segmenti hazırlamadan belleğe yazarım.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Memory', 'Dört adet byte sabiti için en az bellek ayıran veri tanımını seçmen gerekiyor. Ne yaparsın?', 'Her elemanı bir byte ayıran DB tanımını kullanırım.', 'DW kullanıp her sabitin yine bir byte kapladığını varsayarım.', 'DD kullanarak alanı küçülteceğimi kabul ederim.', 'Eleman genişliğini belirtmeden sonraki verilerin adreslerini üst üste bindiririm.', 'microprocessors', 1),
  (gen_random_uuid(), 1, 'Instruction', 'Yeni komut işlendiğinde önce bellekten alınması gerekiyor. Bu aşamayı nasıl adlandırırsın?', 'Komutun bellekten getirildiği fetch aşamasını başlatırım.', 'IR''deki eski komutu decode edip yeni fetch tamamlanmadan yürütmeyi sürdürürüm.', 'Interrupt aşamasını her komutun zorunlu ilk adımı sayarım.', 'Opcode elde edilmeden rastgele bir işlemi uygularım.', 'microprocessors', 1),
  (gen_random_uuid(), 2, 'Addressing', 'Bir veri adresi segment ve ofset olarak tutuluyor. 8086 fiziksel adresini nasıl üretirsin?', 'Segment değerini 16 ile çarpıp ofseti eklerim.', 'Segment ile ofseti doğrudan toplayıp kaydırmayı atlarım.', 'Ofseti 16 ile çarpıp segmenti değişmeden eklerim.', 'Taşma ve adres genişliğini izlemeden sonucu bellek erişimine veririm.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Addressing', 'DS doğru ayarlı; tablo elemanı BX tabanı ve sabit displacement ile seçilecek. Etkin ofseti nasıl bulursun?', 'BX ile displacement değerini toplayıp DS içindeki segmentle erişirim.', 'DS ile BX''i toplayıp displacement değerini segment sayarım.', 'IP değerini tablo ofsetine ekleyerek veri adresi üretirim.', 'Toplamın ofset sınırını denetlemeden yanlış segmentteki veriyi güncellerim.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Addressing', 'BP tabanlı yerel değişken erişimi beklenmedik segmentten okuyor. Varsayılan segment seçiminde neyi hesaba katarsın?', 'BP tabanlı erişimin varsayılan olarak SS kullandığını dikkate alırım.', 'BP kullanılan her durumda DS''nin seçileceğini varsayarım.', 'CS''yi yerel değişken segmenti olarak ayarlarım.', 'Segment override gerekmesini incelemeden yanlış alanı yazmaya devam ederim.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Assembly', 'İki byte parçasından oluşan 16 bit toplamı düşük byte''tan başlayarak hesaplıyorsun. Üst byte işleminde ne yaparsın?', 'Düşük byte ADD işleminden gelen carry''yi üst byte''a ADC ile eklerim.', 'Üst byte için tekrar ADD kullanıp düşük byte carry''sini yok sayarım.', 'ADC''yi düşük byte''ta kullanıp üst byte''a carry taşımam.', 'Carry kaybına rağmen bozuk toplamı doğru uzunluk değeri olarak kullanırım.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Assembly', 'On altı bitlik işaretsiz çarpımın tam 32 bit sonucu saklanacak. MUL sonrasında nasıl toplarsın?', 'Sonucun üst 16 bitini DX''ten, alt 16 bitini AX''ten alırım.', 'Yalnızca AX''i saklayıp DX''in sonuca ait olmadığını varsayarım.', 'BX ve CX''in otomatik olarak sonuç çiftine dönüştüğünü kabul ederim.', 'DX doluyken üst yarıyı atıp taşmış sonucu hesap bakiyesine yazarım.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Assembly', 'İki packed BCD değer ADD ile toplandı ve sonuç ondalık basamak olarak geçersiz. Nasıl düzeltirsin?', 'İkili toplamdan sonra DAA uygulayıp sonucu geçerli packed BCD biçimine ayarlarım.', 'DAA''yı toplama öncesinde çalıştırıp operandları otomatik dönüştürmesini beklerim.', 'Sonucu yalnızca ROR ile döndürerek BCD düzeltmesi yaparım.', 'Geçersiz BCD nibble''larını denetlemeden ekranda ondalık değer diye gösteririm.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Stack', 'Bir alt yordam çağrısından sonra doğru komuta dönülmesi gerekiyor. CALL ve RET akışını nasıl korursun?', 'CALL''ın dönüş adresini yığına koymasına ve RET''in aynı adresi geri almasına izin veririm.', 'CALL öncesinde SP''yi sıfırlayıp dönüş adresinin sabit yerde kalacağını varsayarım.', 'RET yerine JMP kullanıp yığındaki dönüş adresinin temizleneceğini beklerim.', 'Alt yordam içinde dönüş adresinin üstüne veri yazıp RET çalıştırırım.', 'microprocessors', 2),
  (gen_random_uuid(), 3, 'Interrupt', 'Bir kesme alt yordamından çıkarken programın bayrakları ve yürütme konumu geri yüklenmeli. Hangi dönüşü kullanırsın?', 'IP, CS ve FLAGS durumunu yığından geri alan IRET kullanırım.', 'RET kullanıp FLAGS ve CS''nin kendiliğinden geri geleceğini varsayarım.', 'JMP ile ana programa dönüp yığın çerçevesini olduğu gibi bırakırım.', 'Kesme bağlamını geri yüklemeden rastgele yığın adresine dallanırım.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Interrupt', 'Maskelenebilir bir donanım kesmesini geçici olarak ertelemek istiyorsun. Hangi durumu yönetirsin?', 'INTR kabulünü etkileyen Interrupt Flag durumunu kontrollü biçimde yönetirim.', 'NMI girişinin de Interrupt Flag ile maskeleneceğini varsayarım.', 'Direction Flag''i temizleyerek bütün kesmeleri kapatırım.', 'Kritik bölümden çıkarken kesme kabul durumunu eski hâline getirmem.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Assembly', 'Kaynak byte dizisini hedefe ileri yönde kopyalayacaksın. MOVSB öncesinde hangi yazmaçları hazırlarsın?', 'Kaynak için DS:SI, hedef için ES:DI adreslerini ayarlarım.', 'Kaynağı SS:SP, hedefi CS:IP üzerinden seçerim.', 'SI ve DI''yi hazırlamadan MOVSB''nin dizileri kendiliğinden bulmasını beklerim.', 'Hedef segmenti doğrulamadan kod bölümünün üzerine kopyalama yaparım.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Assembly', 'MOVSB ile 80 byte kopyalama tekrarı gerekiyor. Elle dallanmak yerine nasıl kurarsın?', 'CX''i 80 yapıp REP MOVSB kullanırım.', 'DX''i 80 yapıp REP''in DX''i otomatik azaltmasını beklerim.', 'CX''i sıfır bırakıp REP''in hedef uzunluğunu bellekten bulacağını varsayarım.', 'Sayaç hazırlamadan REP başlatıp bellek sınırını aşmasına izin veririm.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Flag', 'String kopyasının düşük adresten yüksek adrese ilerlemesi gerekiyor. Yönü nasıl ayarlarsın?', 'CLD ile Direction Flag''i temizleyip SI ve DI''nin artmasını sağlarım.', 'STD kullanıp indislerin ileri yönde artacağını varsayarım.', 'Carry Flag''i temizleyerek string yönünü belirlerim.', 'Direction Flag''in önceki değerini bilmeden kopyalamayı başlatırım.', 'microprocessors', 2),
  (gen_random_uuid(), 3, 'Bus', 'DMA denetleyicisi sistem veri yolunu istiyor. 8086 HOLD isteğine nasıl karşılık vermeli?', 'Mevcut veri yolu çevrimini tamamlayıp yolu bırakarak HLDA üretmesini beklerim.', 'HOLD aktifken yeni bellek çevrimleri başlatıp HLDA''yı gecikmesiz yükseltirim.', 'INTR sinyalini HLDA yerine kullanarak yol sahipliğini devrederim.', 'Veri yolu sürücülerini bırakmadan DMA aygıtına erişim izni veririm.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Memory', 'Byte adreslenebilir 8 KB bellek çipi tasarlıyorsun. Çip içindeki konumlar için kaç adres biti gerekir?', '8192 konumu seçmek için 13 adres biti ayırırım.', 'Veri yolu sekiz bit olduğu için sekiz adres bitinin yeterli olduğunu varsayarım.', 'Kapasiteyi byte yerine bit sayıp 16 adres biti ayırırım.', 'Eksik adres hattıyla birden çok konumu aynı adrese eşlerim.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Memory', 'Bir bellek çipi 40000h adresinden başlayıp 16 KB alan kaplıyor. Bitiş adresini nasıl belirlersin?', 'Başlangıca 16 KB eksi bir ekleyerek son geçerli byte adresini bulurum.', 'Başlangıca doğrudan 16 KB ekleyip ilk geçersiz adresi son adres sayarım.', 'Veri yolu genişliğini başlangıç adresinden çıkarırım.', 'Adres aralığını hesaplamadan sonraki çevre birimiyle üst üste bindiririm.', 'microprocessors', 2),
  (gen_random_uuid(), 2, 'Debugging', 'Signed toplama taşmış olmasına rağmen kod yalnızca Carry Flag''e bakıp sonucu geçerli sayıyor. Dallanmayı nasıl düzeltirsin?', 'Signed taşma kararını Overflow Flag üzerinden veririm.', 'Carry Flag sıfırsa signed sonucun her zaman geçerli olduğunu kabul ederim.', 'Sign Flag''i signed taşmanın tek göstergesi olarak kullanırım.', 'Taşmış signed değeri sınır denetimi olmadan dizi indeksi olarak kullanırım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Debugging', 'CMP ile JNE arasına bayrakları değiştiren ADD eklendi ve dal yanlış çalışıyor. Ne yaparsın?', 'JNE''nin CMP sonucunu kullanması için araya bayrak değiştiren komut koymam.', 'JNE''nin önceki bütün bayrak sonuçlarını sakladığını varsayarım.', 'ADD sonrasındaki Carry Flag''i eşitsizlik koşulu olarak kullanırım.', 'Yanlış dala gidildiğini bilerek işlem sonucunu üretim belleğine yazarım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Interrupt', 'Kritik bölümde INTR kapalıyken NMI yine alt yordamı başlatıyor. Tasarımı nasıl yorumlarsın?', 'NMI maskelenemediği için kritik durumu NMI alt yordamıyla güvenli paylaşacak biçimde korurum.', 'Interrupt Flag temizlenince NMI''nin de engellenmesi gerektiğini varsayarım.', 'NMI hattını yazılımdan INTR olarak yeniden adlandırırım.', 'NMI sırasında paylaşılan durumu yarım güncellenmiş hâliyle kullanırım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Interrupt', 'Kesme alt yordamı AX ve DX''i değiştirince ana programın hesabı bozuluyor. Bağlamı nasıl korursun?', 'Alt yordamın değiştirdiği yazmaçları girişte saklar, çıkışta ters sırayla geri yüklerim.', 'Yalnızca dönüş adresini koruyup genel yazmaçların önemsiz olduğunu varsayarım.', 'Yazmaçları çıkışta sıfırlayarak eski değerlerine döndürdüğümü kabul ederim.', 'Bozulan yazmaçlarla ana programı sürdürüp hatayı sonraki kesmeye bırakırım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Stack', 'Kesme alt yordamında fazladan PUSH yapıldı ancak karşılık gelen POP unutuldu. IRET neden yanlış yere dönebilir?', 'SP beklenen konumda olmadığı için IRET dönüş bağlamı yerine başka yığın verilerini okuyabilir.', 'IRET yığını kullanmadığı için fazladan PUSH''ın etkisiz olduğunu varsayarım.', 'CS değerini sıfırlamanın yığın dengesini düzelteceğini kabul ederim.', 'Dengesiz yığınla IRET çalıştırıp belirsiz adresi yürütmeye başlarım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Stack', 'Yakın alt yordam içinde SP elle değiştirildi ve RET yanlış ofseti aldı. Hangi disiplini uygularsın?', 'Yerel yığın kullanımını dengeler, RET öncesinde SP''yi çağrı sonrasındaki dönüş adresine getiririm.', 'RET''in dönüş adresini IP yerine DS''den bulacağını varsayarım.', 'SP''yi rastgele bir çift adrese yuvarlayarak doğru dönüşü beklerim.', 'Dönüş adresini doğrulamadan bozuk yığın üzerinden kod yürütürüm.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Assembly', 'Kaynak ve hedef bölgeler örtüşüyor; ileri MOVSB henüz okunmamış byte''ları eziyor. Kopyayı nasıl güvenli yaparsın?', 'Hedef daha yüksek adresteyse uç adreslerden başlayıp DF set ederek geriye doğru kopyalarım.', 'Her durumda CLD ile ileri kopyalayıp örtüşmenin sonucu değiştirmeyeceğini varsayarım.', 'Yalnızca CX''i artırarak ezilen kaynak byte''larını geri getirmeye çalışırım.', 'Örtüşmeyi denetlemeden kritik veriyi yerinde REP MOVSB ile bozarım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Bus', 'HLDA aktifken işlemci de bellek yazma sinyallerini sürüyor ve veri yolu çakışıyor. Ne yaparsın?', 'HLDA süresince işlemcinin adres, veri ve denetim yolu sürücülerini bırakmasını sağlarım.', 'Yalnızca adres yolunu bırakıp veri ve yazma sinyallerini sürmeye devam ederim.', 'DMA ile işlemcinin aynı anda yazmasının değeri hızlandıracağını varsayarım.', 'Çakışan sürücüleri etkin bırakıp elektriksel sonucu geçerli veri sayarım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Memory', 'İki bellek çipi aynı adreslerde seçiliyor ve okuma sırasında farklı veri sürüyor. Adres decode mantığını nasıl düzeltirsin?', 'Chip-select koşullarını çakışmayacak adres aralıkları üretecek biçimde yeniden kurarım.', 'İki chip-select hattını birlikte etkin tutup güçlü sürücünün kazanmasını beklerim.', 'Read denetimini ortak bırakıp iki çipten gelen değerlerin aynı olacağını varsayarım.', 'Çakışan değerleri yazılımda rastgele seçip donanım hatasını gizlerim.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'Memory', '16 KB çip yalnızca alt 13 adres hattıyla bağlandığı için içerik iki kez aynalanıyor. Sorunu nasıl giderirsin?', 'Çip içi adresleme için gereken 14 hattı bağlar ve üst hatları chip-select decode''unda kullanırım.', 'Aynalanmayı azaltmak için bir adres hattını veri yoluna bağlarım.', 'Eksik hattı sabit 0 yapıp bütün 16 KB''nin erişilebilir olacağını varsayarım.', 'Aynı fiziksel hücreleri farklı adresler sanıp iki bağımsız tampon olarak kullanırım.', 'microprocessors', 3),
  (gen_random_uuid(), 3, 'I/O', '8255 mode 0''da Port A giriş, Port B çıkış olacak; mevcut kontrol sözcüğü ikisini de giriş yapıyor. Ne yaparsın?', 'Mode-set kontrol sözcüğünde her portun yön bitlerini istenen giriş/çıkışa göre yeniden kodlarım.', 'Port A veri yazmacına yön değerini yazarak Port B''nin de çıkış olmasını beklerim.', 'Mode 2''yi bütün portlara açıp tek yönlü aktarım elde ederim.', 'Yanlış yöndeki çıkış sürücüsünü harici aygıtla karşı karşıya bırakırım.', 'microprocessors', 3),
